<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048 Game</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    min-height: 100%;
    background: #faf9f0;
    color: #111;
    font-family: Arial, Helvetica, sans-serif;
  }

  body {
    overflow-x: hidden;
  }

  .page {
    width: 100%;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .game-wrap {
    width: 500px;
    max-width: calc(100vw - 40px);
    padding-top: 8px;
    text-align: center;
  }

  .game-header {
    position: relative;
    width: 100%;
  }

  .game-modes {
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    font-size: 13px;
    font-weight: 700;
  }

  .mode {
    border: 0;
    background: transparent;
    padding: 5px 10px;
    border-radius: 5px;
