    justify-content: space-between;
    align-items: flex-start;
  }

  .score-area {
    display: flex;
    gap: 7px;
  }

  .score-box {
    min-width: 68px;
    height: 51px;
    border-radius: 3px;
    background: #b59a7e;
    color: #fff;
    text-align: center;
    padding-top: 6px;
    font-weight: 700;
  }

  .score-label {
    display: block;
    font-size: 10px;
    line-height: 12px;
    opacity: .92;
  }

  .score-value {
    display: block;
    font-size: 19px;
    line-height: 20px;
  }

  .new-game {
    border: 0;
    border-radius: 3px;
    background: #b69473;
    color: white;
    font-weight: 700;
    font-size: 14px;
    padding: 14px 18px;
    cursor: pointer;
  }

  .board {
    width: 500px;
    height: 500px;
    max-width: 100%;
    background: #b9aa9d;
    border-radius: 5px;
    padding: 10px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(4, 1fr);
    gap: 10px;
    touch-action: none;
    user-select: none;
  }

  .tile {
    border-radius: 3px;
    background: #c9bdb1;
