  .tile.n2 { background: #eee5db; }
  .tile.n4 { background: #eee1c8; }
  .tile.n8 { background: #f2aa70; color: #fff; }
  .tile.n16 { background: #f58262; color: #fff; }
  .tile.n32 { background: #f66b50; color: #fff; }
  .tile.n64 { background: #f84d32; color: #fff; }
  .tile.n128 { background: #edcf72; color: #fff; font-size: 37px; }
  .tile.n256 { background: #edcc61; color: #fff; font-size: 37px; }
