  .game-link:nth-child(2) { border-top-color: #a8c8f5; }
  .game-link:nth-child(3) { border-top-color: #a6e6d4; }
  .game-link:nth-child(4) { border-top-color: #20a94e; }

  .scroll-top {
    position: fixed;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 58px;
    height: 28px;
    background: #fff;
    border: 1px solid #ccc;
    border-bottom: 0;
    border-radius: 5px 5px 0 0;
    font-size: 19px;
    cursor: pointer;
  }

  @media (max-width: 600px) {
    .game-wrap { padding-top: 5px; }
    h1 { font-size: 25px; }
    .board {
      width: min(500px, calc(100vw - 20px));
      height: min(500px, calc(100vw - 20px));
      gap: 7px;
      padding: 7px;
