    .tile { font-size: 9vw; }
    .tile.n128, .tile.n256, .tile.n512 { font-size: 7vw; }
    .tile.n1024, .tile.n2048 { font-size: 6vw; }
    .instructions, .other-games {
      margin-left: calc((min(500px, 100vw - 20px) - 100vw) / 2);
